using FluentValidation;namespace Namaa.Application.Invoices.Commands.CreateInvoice;public sealed class CreateInvoiceCommandValidator:AbstractValidator<CreateInvoiceCommand>{public CreateInvoiceCommandValidator(){RuleFor(x=>x.InvoiceNumber).NotEmpty().MaximumLength(30);RuleFor(x=>x.CreatedByUserId).GreaterThan(0);RuleFor(x=>x.DueDate).GreaterThanOrEqualTo(x=>x.IssueDate).When(x=>x.DueDate.HasValue);}}
